     *   permitted to bypass.
     */
    fun pullsMergeAsync(
        clientConfig: ClientConfig,
        request: Pulls.PullsMergeAsyncRequest,
        options: RequestOptions? = null,
    ): PullRequestMergeAsyncResult {
        return SdkClient.request<PullRequestMergeAsyncResult>(
                SdkClient.RequestSpec(
                    "PUT",
